CREATE TABLE ibexa_dfs_file (name_hash VARCHAR(34) DEFAULT '' NOT NULL, name TEXT NOT NULL, name_trunk TEXT NOT NULL, datatype VARCHAR(255) DEFAULT 'application/octet-stream' NOT NULL, scope VARCHAR(25) DEFAULT '' NOT NULL, size BIGINT DEFAULT 0 NOT NULL, mtime INT DEFAULT 0 NOT NULL, expired BOOLEAN DEFAULT 'false' NOT NULL, status BOOLEAN DEFAULT 'false' NOT NULL, PRIMARY KEY(name_hash));
